                    bodyStr = colorJsonString(bodyStr, false, tty)
                }
                fmt.Printf("\n%s\n", bodyStr)
                os.Exit(1)
            } else {
                prettyBody := out.String()
                if tty {
                    prettyBody = colorJsonString(prettyBody, true, tty)
                }
                // Print with leading newline?
