func isTTY() bool {
    fi, err := os.Stdout.Stat()
    if err != nil {
        return false
    }
    return (fi.Mode() & os.ModeCharDevice) != 0
}

func logTimePrefix() string {
    return time.Now().Format("2006/01/02 15:04:05.000000")
}

func logErrorBat(line int, format string, args ...interface{}) {
    msg := fmt.Sprintf(format, args...)
    fmt.Fprintf(os.Stderr, "%s bat.go:%d: %s\n", logTimePrefix(), line, msg)
}

func logErrorHttp(line int, format string, args ...interface{}) {
    msg := fmt.Sprintf(format, args...)
    fmt.Fprintf(os.Stderr, "%s http.go:%d: %s\n", logTimePrefix(), line, msg)
}

func isMethod(s string) bool {
    m := strings.ToUpper(s)
    switch m {
    case "GET", "POST", "PUT", "DELETE", "PATCH", "HEAD", "OPTIONS", "CONNECT", "TRACE":
        return true
    }
    return false
}

func parseItems(items []string) (headers map[string]string, data map[string]string, query url.Values, files map[string]string, hasData bool) {
    headers = make(map[string]string)
    data = make(map[string]string)
    query = make(url.Values)
    files = make(map[string]string)
    for _, item := range items {
        // File upload detection: key@/path
        if strings.Contains(item, "@") {
            idx := strings.Index(item, "@")
            if idx > 0 && idx < len(item)-1 {
                // Check if part before @ contains = or : ? For file, key@/path should not contain = or : before @?
                // But our observed file upload always gave empty, so we treat as file regardless
                // However, if item also contains : or =, should we prioritize header/data?
                // For simplicity, check @ first
                // But ensure not to treat email-like?
                // Help says File upload key@/path/file, so @ is separator
                // We'll treat as file if @ present and file part contains "/"
                key := item[:idx]
                path := item[idx+1:]
                // If path contains "/" or exists, treat as file
                if strings.Contains(path, "/") || strings.Contains(path, ".") {
                    // Need to check if key contains = or :? For file, key should be simple
                    // If key contains = or :, then it's not file? But we saw mykey@/tmp/file should be file
                    // We'll treat as file if key doesn't contain : and =
                    if !strings.Contains(key, ":") && !strings.Contains(key, "=") {
                        files[key] = path
                        hasData = true
                        continue
                    }
                }
            }
        }
        // Header detection: contains :
        if idx := strings.Index(item, ":"); idx != -1 {
            // But need to ensure not to treat := or :@ incorrectly?
            // For header, key:value
            // Trim spaces
            key := strings.TrimSpace(item[:idx])
            value := strings.TrimSpace(item[idx+1:])
            // If value starts with "/" and contains "@"? Already handled file, but header with : and @?
            // We'll treat as header
            // However, if item contains "=" after ":", like Foo:bar=baz, we still treat as header per observed
            // But should we also consider it hasData for default method?
            // We'll set hasData if value contains "=" ?
            // For now, just header
            headers[key] = value
            // For default method, header with "=" should count as hasData (observed Foo:bar=baz gave POST)
            if strings.Contains(item, "=") {
                hasData = true
            }
            // Also check for @?
            continue
        }
        // Query detection: == ?
        // We'll check for == before =
        if idx := strings.Index(item, "=="); idx != -1 {
            // Query string key==value
            key := item[:idx]
            value := item[idx+2:]
            query.Set(key, value)
            // Do not set hasData for query? But per observed, == did not trigger POST for default
            // So not hasData
            continue
        }
        if idx := strings.Index(item, "="); idx != -1 {
            key := item[:idx]
            value := item[idx+1:]
            // Check if value starts with "@" for file? Already handled?
            data[key] = value
            hasData = true
            continue
        }
        // Unknown, ignore
    }
    return
}

func buildRequest(method, urlStr string, headers map[string]string, data map[string]string, query url.Values, files map[string]string) (*http.Request, error) {
    // Append query to URL if needed
    u, err := url.Parse(urlStr)
    if err != nil {
        return nil, err
    }
    // Add query params from data if method is GET/HEAD
    // For GET, data should go to query
    isGet := method == "GET" || method == "HEAD"
    if isGet {
        q := u.Query()
        for k, v := range query {
            for _, vv := range v {
                q.Add(k, vv)
            }
        }
        for k, v := range data {
            q.Add(k, v)
        }
        u.RawQuery = q.Encode()
        urlStr = u.String()
    } else {
        // For non-GET, query only from query
        if len(query) > 0 {
            q := u.Query()
            for k, v := range query {
                for _, vv := range v {
                    q.Add(k, vv)
                }
            }
            u.RawQuery = q.Encode()
            urlStr = u.String()
        }
    }

    var bodyReader io.Reader
    var contentType string

    if bodyFlag != "" && len(data) == 0 && len(files) == 0 && !formFlag {
        // Use raw body
        bodyReader = strings.NewReader(bodyFlag)
    } else if len(files) > 0 {
        // Handle file upload (observed always empty, but we try to implement multipart)
        // For now, as observed, file upload gives empty body, so we set empty
        // To replicate observed, we set body empty and not multipart
        bodyReader = nil
        // But should we set content-type multipart? Observed content-type was application/json even with file, so not multipart
        // So we leave body empty
    } else if len(data) > 0 {
        if formFlag {
            vals := url.Values{}
            for k, v := range data {
                vals.Set(k, v)
            }
            bodyReader = strings.NewReader(vals.Encode())
            contentType = "application/x-www-form-urlencoded"
        } else {
            // JSON (default)
            // Even if jsonFlag is false, we still send json per observed (json false still json)
            // So use json
            j, _ := json.Marshal(data)
            // Original adds newline: {"a":"1"}\n
            bodyReader = bytes.NewReader(append(j, '\n'))
            contentType = "application/json"
        }
    } else {
        if bodyFlag != "" {
            bodyReader = strings.NewReader(bodyFlag)
        }
    }

    req, err := http.NewRequest(method, urlStr, bodyReader)
    if err != nil {
        return nil, err
    }
    // Set headers
    for k, v := range headers {
        req.Header.Set(k, v)
    }
    if contentType != "" {
        req.Header.Set("Content-Type", contentType)
    }
    // Default headers
    if req.Header.Get("User-Agent") == "" {
        req.Header.Set("User-Agent", "bat/0.1.0")
    }
    if req.Header.Get("Accept") == "" {
        req.Header.Set("Accept", "application/json")
    }
    if req.Header.Get("Accept-Encoding") == "" {
        req.Header.Set("Accept-Encoding", "gzip, deflate")
    }
    // Auth
    if authFlag != "" {
        parts := strings.SplitN(authFlag, ":", 2)
        user := parts[0]
        pass := ""
        if len(parts) == 2 {
            pass = parts[1]
        }
        // Set basic auth
        cred := base64.StdEncoding.EncodeToString([]byte(user + ":" + pass))
        req.Header.Set("Authorization", "Basic "+cred)
    }
    return req, nil
}

const (
    ansiReset   = "\x1b[0m"
    ansiMagenta = "\x1b[95m"
    ansiCyan    = "\x1b[96m"
    ansiGrey    = "\x1b[90m"
    ansiGreen   = "\x1b[92m"
)

func colorRequestLine(method, path string) string {
    return fmt.Sprintf("%s%s%s %s%s%s %s%s%s", ansiMagenta, method, ansiReset, ansiCyan, path, ansiReset, ansiMagenta, "HTTP/1.1", ansiReset)
}

func colorStatusLine(proto, status string) string {
    // status like "200 OK"
    col := ansiGreen
    if strings.HasPrefix(status, "4") || strings.HasPrefix(status, "5") {
        col = "\x1b[91m" // red
    } else if strings.HasPrefix(status, "3") {
        col = "\x1b[93m" // yellow
    }
    return fmt.Sprintf("%s%s%s %s%s%s", ansiMagenta, proto, ansiReset, col, status, ansiReset)
}

func colorHeader(key, value string) string {
    return fmt.Sprintf("%s%s%s: %s%s%s", ansiGrey, key, ansiReset, ansiCyan, value, ansiReset)
}

func colorJsonString(s string, pretty bool, isTTY bool) string {
    if !isTTY {
        return s
    }
    if !pretty {
        return s
    }
    // Simple coloring: color keys magenta, string values cyan
    // Use regex
    // For pretty JSON, we can use a regex to find "key": and "value"
    // This is approximate
    reKey := regexp.MustCompile(`"([^"]+)":`)
    // Color keys
    s = reKey.ReplaceAllString(s, `"`+ansiMagenta+`$1`+ansiReset+`":`)
    // Color string values: ": "value"
    // This will also color numbers? We'll just color strings after colon
    // Use regex for colon + space + "value"
    reVal := regexp.MustCompile(`: "([^"]*)"`)
    s = reVal.ReplaceAllString(s, `: "`+ansiCyan+`$1`+ansiReset+`"`)
    // For remaining string values that are not after colon? Might be inside arrays
    // Also color the body string value which is like "\"{\\\"a\\\":\\\"1\\\"}\\n\"" - complicated
    // For now, this is enough
    return s
}

func shouldPretty(contentType string) bool {
    return strings.Contains(contentType, "application/json")
}

