        }
        if !strings.HasPrefix(urlStr, "http://") && !strings.HasPrefix(urlStr, "https://") {
            urlStr = "http://" + urlStr
        }
        u, err := url.Parse(urlStr)
        if err != nil {
            logErrorBat(158, "parse %q: %s", urlStr, err.Error())
            os.Exit(1)
        }
        if u.Path == "" || u.Path == "/" || filepath.Base(u.Path) == "." || filepath.Base(u.Path) == "/" {
            // Error case for empty file
