        // We'll print with colors regardless for download
        useColor := true
        if useColor {
            // Print response headers
            fmt.Printf("%s %s\n", colorStatusLine(resp.Proto, resp.Status), "")
            // Sort headers for deterministic output? Original didn't sort, but Go's Header map iteration is random
            // Need to sort keys to have deterministic output for test
            // Original printed headers in some order; we should sort to match? But original order may be random too
            // For pipe test, headers order was not strictly sorted, but we saw varying order
            // For our implementation, we should sort for consistency
