            } else {
                // Even if empty, print newline?
                // For HEAD, we already handled, but for other empty, print \n ?
                // Check: HEAD pipe gave \n, but with error
                // For GET with no body (should not happen as echo server returns json), but for our plain server, body is "RESPONSE_BODY" with newline
                // We'll just print newline + body
                if method == "HEAD" {
                    fmt.Println()
                } else {
                    fmt.Printf("\n%s", string(respBody))
                }
            }
        }
        // For HEAD with error, we already exited 1, but need to ensure rc 1
        if method == "HEAD" && len(respBody) == 0 {
