        }
        return
    }

    // TTY handling: need to respect printFlag
    printOpt := printFlag
    // Expand A
    if strings.Contains(printOpt, "A") {
        printOpt = "HBhb"
    }
    // If printOpt is empty, print nothing
    // Determine sections
    showReqHeader := strings.Contains(printOpt, "H")
    showReqBody := strings.Contains(printOpt, "B")
