func methodOrDefault(m string, items []string) string {
    if m != "" {
        return m
    }
    // Determine default based on items hasData
    _, _, _, _, hasData := parseItems(items)
    if hasData || bodyFlag != "" {
        return "Post"
    }
    return "Get"
}

func buildClient() *http.Client {
    transport := &http.Transport{}
    if proxyFlag != "" {
        proxyURL, err := url.Parse(proxyFlag)
        if err == nil {
            transport.Proxy = http.ProxyURL(proxyURL)
        } else {
            transport.Proxy = http.ProxyURL(proxyURL)
        }
    }
    if insecureFlag {
        transport.TLSClientConfig = &tls.Config{InsecureSkipVerify: true}
    }
    client := &http.Client{
        Transport: transport,
    }
    return client
}

func runBench(method, urlStr string) {
    client := buildClient()
    // Prepare request template?
    // For bench, we need to handle similar to normal but with same URL and method, no data?
    // Use args from flag.Args() that include items? But bench likely ignores items?
    // For now, just bench the URL with method

    // Need to handle bN and bC defaults
    n := bNFlag
    c := bCFlag
    if n <= 0 {
        n = 1000
    }
    if c <= 0 {
        c = 100
    }
    if c > n {
        c = n
    }

    var wg sync.WaitGroup
    jobs := make(chan int, n)
    results := make(chan time.Duration, n)
    statusCodes := make(map[int]int)
    var mu sync.Mutex
    var total time.Duration
    var slowest time.Duration
    var fastest time.Duration = time.Hour

    // Fill jobs
    for i := 0; i < n; i++ {
        jobs <- i
    }
    close(jobs)

    startAll := time.Now()
    // Workers
    for i := 0; i < c; i++ {
        wg.Add(1)
        go func() {
            defer wg.Done()
            for range jobs {
                start := time.Now()
                req, _ := http.NewRequest(method, urlStr, nil)
                req.Header.Set("User-Agent", "bat/0.1.0")
                req.Header.Set("Accept", "application/json")
                req.Header.Set("Accept-Encoding", "gzip, deflate")
                if authFlag != "" {
                    parts := strings.SplitN(authFlag, ":", 2)
                    user := parts[0]
                    pass := ""
                    if len(parts) == 2 {
                        pass = parts[1]
                    }
                    cred := base64.StdEncoding.EncodeToString([]byte(user + ":" + pass))
                    req.Header.Set("Authorization", "Basic "+cred)
                }
                resp, err := client.Do(req)
                elapsed := time.Since(start)
                results <- elapsed
                mu.Lock()
                total += elapsed
                if elapsed > slowest {
                    slowest = elapsed
                }
                if elapsed < fastest {
                    fastest = elapsed
                }
                if err != nil {
                    // Error distribution?
                    statusCodes[0]++
                } else {
                    statusCodes[resp.StatusCode]++
                    io.Copy(io.Discard, resp.Body)
                    resp.Body.Close()
                }
                mu.Unlock()
            }
        }()
    }
    wg.Wait()
    close(results)
    totalElapsed := time.Since(startAll)

    // Collect results for histogram
    var durs []time.Duration
    for d := range results {
        durs = append(durs, d)
    }
    sort.Slice(durs, func(i, j int) bool { return durs[i] < durs[j] })

    // Print summary
    fmt.Println()
    fmt.Println("Summary:")
    fmt.Printf("  Total:\t%.4f secs.\n", totalElapsed.Seconds())
    if len(durs) > 0 {
        fmt.Printf("  Slowest:\t%.4f secs.\n", slowest.Seconds())
        fmt.Printf("  Fastest:\t%.4f secs.\n", fastest.Seconds())
        avg := total.Seconds() / float64(n)
        fmt.Printf("  Average:\t%.4f secs.\n", avg)
        if totalElapsed.Seconds() > 0 {
            fmt.Printf("  Requests/sec:\t%.4f\n", float64(n)/totalElapsed.Seconds())
        }
        fmt.Println()
        fmt.Println("Status code distribution:")
        // Sort status codes
        codes := make([]int, 0, len(statusCodes))
        for k := range statusCodes {
            codes = append(codes, k)
        }
        sort.Ints(codes)
        for _, code := range codes {
            if code == 0 {
                fmt.Printf("  [Error]\t%d responses\n", statusCodes[code])
            } else {
                fmt.Printf("  [%d]\t%d responses\n", code, statusCodes[code])
            }
        }
        fmt.Println()
        fmt.Println("Response time histogram:")
        // Simplified histogram: 10 buckets
        buckets := 10
        if len(durs) < buckets {
            buckets = len(durs)
        }
        min := fastest.Seconds()
        max := slowest.Seconds()
        step := (max - min) / float64(buckets)
        if step == 0 {
            step = 0.001
        }
        // Count per bucket
        counts := make([]int, buckets)
        for _, d := range durs {
            idx := int((d.Seconds() - min) / step)
            if idx >= buckets {
                idx = buckets - 1
            }
            counts[idx]++
        }
        maxCount := 0
        for _, c := range counts {
            if c > maxCount {
                maxCount = c
            }
        }
        for i := 0; i < buckets; i++ {
            val := min + float64(i)*step
            barLen := 0
            if maxCount > 0 {
                barLen = counts[i] * 40 / maxCount
            }
            bar := strings.Repeat("∎", barLen)
            fmt.Printf("  %.3f [%d]\t|%s\n", val, counts[i], bar)
        }
        fmt.Println()
        fmt.Println("Latency distribution:")
        if len(durs) > 0 {
            percentiles := []int{10, 25, 50, 75, 90, 95, 99}
            for _, p := range percentiles {
                idx := int(float64(p) / 100 * float64(len(durs)))
                if idx >= len(durs) {
                    idx = len(durs) - 1
                }
                fmt.Printf("  %d%% in %.4f secs.\n", p, durs[idx].Seconds())
            }
        }
    } else {
        fmt.Printf("  Total:\t%.4f secs.\n", totalElapsed.Seconds())
    }

    // If there were errors, print error distribution
    // But we already did status code
    // For original, when bench had no -b.N etc, it used default 1000, but our case with -bench alone and no N/C gave timeout for original? But we handle.
}
